// Alert mode only runs 21:00–04:30 SGT (US market hours overlap)
const parts = Object.fromEntries(
  new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Singapore', hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  }).formatToParts(new Date()).map(x => [x.type, x.value]));
const h = parseInt(parts.hour, 10);
const m = parseInt(parts.minute, 10);
const inWindow = h >= 21 || h < 4 || (h === 4 && m <= 30);
if (!inWindow) return [];
return [{ json: { sgtTime: `${parts.hour}:${parts.minute} SGT` } }];

// Decide whether to fire the extreme-fear alert and build its message.
const THRESHOLD = 10;
const COOLDOWN_MINUTES = 120;

const first = (name) => { try { return $(name).first().json; } catch (e) { return null; } };

let score = null;
let sourceName = 'CNN';
const cnn = first('Fetch CNN');
if (cnn && cnn.fear_and_greed && typeof cnn.fear_and_greed.score === 'number') {
  score = Math.round(cnn.fear_and_greed.score);
} else {
  const mirror = first('Fetch Mirror');
  let raw = null;
  if (mirror && mirror.score != null) {
    raw = typeof mirror.score === 'number' ? mirror.score
        : (typeof mirror.score.score === 'number' ? mirror.score.score : null);
  }
  if (raw !== null) { score = Math.round(raw); sourceName = 'feargreedchart.com'; }
}
if (score === null) throw new Error('Could not fetch the Fear & Greed score from CNN or the mirror');

if (score >= THRESHOLD) return [];

// Cooldown so a low score doesn't alert every 30 minutes all night
const sd = $getWorkflowStaticData('global');
const now = Date.now();
if (sd.lastAlertTs && (now - sd.lastAlertTs) / 60000 < COOLDOWN_MINUTES) return [];
sd.lastAlertTs = now;

const label = score <= 20 ? 'Extreme Fear' : 'Fear';

// CNN's 7 component indicators (score + rating; the mirror has no equivalent)
let breakdown = '  (Component breakdown not available)';
if (sourceName === 'CNN') {
  const comps = [
    ['Market Momentum (S&P500)', 'market_momentum_sp500'],
    ['Stock Price Strength',     'stock_price_strength'],
    ['Stock Price Breadth',      'stock_price_breadth'],
    ['Put/Call Options',         'put_call_options'],
    ['Market Volatility (VIX)',  'market_volatility_vix'],
    ['Junk Bond Demand',         'junk_bond_demand'],
    ['Safe Haven Demand',        'safe_haven_demand'],
  ];
  const lines = comps.map(([n, k]) => {
    const c = cnn[k];
    return c && typeof c.score === 'number'
      ? `  • ${n}: ${Math.round(c.score)}/100 (${c.rating || '?'})` : null;
  }).filter(Boolean);
  if (lines.length) breakdown = lines.join('\n');
}

const sgtTime = $('Window Check').first().json.sgtTime;

const text = [
  '🚨 EXTREME FEAR ALERT 🚨',
  '',
  `📊 Fear & Greed Index: ${score} (${label})`,
  `🕐 Checked at: ${sgtTime}`,
  '',
  '📉 Component Breakdown:',
  breakdown,
  '',
  `⚠️ Index is below ${THRESHOLD} — market in extreme fear territory.`,
  '',
  `Source: ${sourceName}`,
].join('\n');

return [{ json: { text } }];
